head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//지표 발행기관 찾기
scwin.vScrenID = "ULDINS91400.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : 지표, 발행기관 조회
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS91400_LIST1_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listStdCdIndcInfoFindInquiry1";
    dts_List1.DataID = encodeURI(url);
    dts_List1.reset();
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS91400_LIST2_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listStdCdIndcInfoFindInquiry2";
    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List1_OnLoadError = function() {
    $c.stf.alert_error(dts_List1);
};
scwin.dts_List2_OnLoadError = function() {
    $c.stf.alert_error(dts_List2);
};
scwin.gform_onload = function() {
    scwin.ins_search();
};
scwin.grd_Grid1_OnDblClick = async function(row, colid) {
    var CD_VAL = dts_List1.getCellData(dts_List1.getRowPosition(), "CD_VAL");
    var INDIC_ISUR_CD = dts_List2.getCellData(row, "INDIC_ISUR_CD");
    var INDIC_ISUR_NM = dts_List2.getCellData(row, "INDIC_ISUR_NM");
    $c.frame.path("../").ins_popupRtn_cdnm(CD_VAL + INDIC_ISUR_CD, INDIC_ISUR_NM);
    await $c.frame.CloseFrame();
};
